# Textos corregidos de los 25 cambios pedidos (7 de octubre de 2026). Salida: txt.json = {id: {campos a cambiar, "hecho": ...}}
import json, re, copy
P2 = "/tmp/claude-0/-home-claude-erreklamatu-rrss/e7eefa61-a30f-57c7-bc2e-7996fd2458cc/scratchpad/p2/publicaciones/"
def pieza(p): return json.load(open(P2 + p + ".json", encoding="utf8"))
def largo_x(t):
    t = re.sub(r"https?://\S+", "x" * 23, t); n = 0
    for ch in t:
        o = ord(ch)
        if o in (0xFE0F, 0x200D): continue
        n += 2 if (o >= 0x1F000 or 0x2600 <= o <= 0x27BF or 0x2300 <= o <= 0x23FF or o in (0x2B50, 0x2705)) else 1
    return n
