CONT = "📞 944 027 596\n✉️ info@erreklamatu.com"
U = {}
def pon(p, hecho, textos=None, **campos):
    d = pieza(p); t = copy.deepcopy(d["textos"]); t.update(textos or {})
    U[p] = dict(campos, textos=t, hecho=hecho)

