# ------------------------------------------------------------------ EITB, programa de 2017: fuera el año
def sin2017(s):
    s = s.replace(" en EITB (vídeo de archivo, de 2017)", " en EITB").replace(" en EITB (2017)", " en EITB")
    return s
N17a = "El crédito y los textos dicen que es de archivo."; N17b = "Ni el crédito del vídeo ni los textos dicen ya el año: lo pediste el 7/10 («le quita actualidad al vídeo, y este sigue vigente»)."
H17 = "Quitado el año: los textos decían «en EITB (2017)» y «en EITB (vídeo de archivo, de 2017)» y ahora dicen «en EITB». También en el vídeo, rehecho: el crédito pasa de «Imágenes: EITB (2017)» a «Imágenes: EITB». El corte y los subtítulos no cambian."
for p in ("PUB-0166", "PUB-0167", "PUB-0168", "PUB-0169", "PUB-0170", "PUB-0178"):
    d = pieza(p); t = {k: sin2017(v) for k, v in d["textos"].items()}; hecho = H17
    if p == "PUB-0166":
        t["x"] = "✈️ Las tres reclamaciones aéreas más habituales:\n\n1️⃣ Retrasos y cancelaciones.\n2️⃣ Maletas extraviadas o dañadas.\n3️⃣ Overbooking.\n\nLo explicaba Jon Ortiz, abogado de #Erreklamatu, en EITB"
        hecho = "Quitado el año. En X, donde decía «“En ese orden”, confirma Jon Ortiz, abogado de #Erreklamatu, en EITB (2017)» pone ahora tu frase: «Lo explicaba Jon Ortiz, abogado de #Erreklamatu, en EITB». En Facebook, Instagram y YouTube, «en EITB (2017)» y «en EITB (vídeo de archivo, de 2017)» pasan a «en EITB». También en el vídeo, rehecho: el crédito pasa de «Imágenes: EITB (2017)» a «Imágenes: EITB». El corte y los subtítulos no cambian."
    if p == "PUB-0178": hecho += " Sigue siendo una pieza para verano («ahora nosotros en verano tenemos un repunte…»)."
    assert all("2017" not in v for v in t.values()), (p, t)
    U[p] = dict(textos=t, hecho=hecho, notas=d["notas"].replace("VÍDEO DE 2017:", "VÍDEO ANTIGUO (2017):").replace(N17a, N17b))
